var frag=`
#ifdef GL_ES
precision highp float;
#endif

uniform vec2 resolution;
uniform float time;
uniform float second;

float rand(vec2 f)  {
return fract(sin(dot(f , vec2(14.9898,second+78.233))) * 43758.5453);
}
//Simple raymarching sandbox with camera

//Raymarching Distance Fields
//About http://www.iquilezles.org/www/articles/raymarchingdf/raymarchingdf.htm
//Also known as Sphere Tracing

//Util Start
vec2 ObjUnion(in vec2 obj0,in vec2 obj1){
  if (obj0.x<obj1.x)
  	return obj0;
  else
  	return obj1;
}
//Util End

//Scene Start
//IQs RoundBox (try other objects http://www.iquilezles.org/www/articles/distfunctions/distfunctions.htm)
vec2 obj1(in vec3 p,float f){
  return vec2(f*length(max(abs(p/f)-vec3(1.0),0.0))-.25-sin(3.0*p.x/f)*sin(3.0*p.y/f)*sin(3.0*p.z/f)*.4,1.0);
}
vec2 sphere(in vec3 p,float f){
  return vec2(f*length(p/f)-1.0,1.0);
}
float torus( vec3 p, vec2 t)
{
  vec2 q = vec2(length(p.xz)-t.x,p.y);
  return length(q)-t.y;
}
//RoundBox with simple solid color
vec3 obj1_c(in vec3 p){
	return vec3(1.0,0.5,0.2);
}
//repeated object
vec2 opRepVar( vec3 p, vec3 c,float f)
{
    vec3 q = mod(p,c)-0.5*c;
    float id = rand(floor(p.xy/c.xy)+1.23*floor(p.yz/c.yz)+3782.1*floor(p.zx/c.zx));
    return id<.33 ? obj1(q,f) :
           id <.66 ? vec2(torus(q,vec2(1.5,.5)),f) :
           sphere(q,f);
}

//Scene End

void main(void){
  vec2 vPos=-1.0+2.0*gl_FragCoord.xy/resolution.xy;

  //Camera animation
  vec3 vuv=vec3(0,1,0);//Change camere up vector here
  vec3 vrp=vec3(0,0,0); //Change camere view here
  vec3 prp=vec3(-sin(.1*time)*8.0,2.5,cos(.1*time)*8.0); //Change camera path position here

  //Camera setup
  vec3 vpn=normalize(vrp-prp);
  vec3 u=normalize(cross(vuv,vpn));
  vec3 v=cross(vpn,u);
  vec3 vcv=(prp+vpn);
  vec3 scrCoord=vcv+vPos.x*u*resolution.x/resolution.y+vPos.y*v;
  vec3 scp=normalize(scrCoord-prp);

  //Raymarching
  const vec3 e=vec3(.1,0,0);
  const float maxd=60.0; //Max depth

  vec2 s=vec2(0.1,0.0);
  vec3 c,p,n;
	c=vec3(1.0,0.5,0.2);
  float f=1.0;
	vec3 ecart=vec3(9.0);
 float dia=1.0;
  for(int i=0;i<256;i++){//noprotect
    if (abs(s.x)<.01||f>maxd) break;
    f+=s.x;
    p=prp+scp*f;
    s=opRepVar(p,ecart,dia);
  }
  if (f<maxd){
	c=vec3(rand(floor(p.xy/ecart.xy)),rand(floor(p.yz/ecart.yz)),rand(floor(p.xz/ecart.xz)));
    n=normalize(
      vec3(s.x-opRepVar(p-e.xyy,ecart,dia).x,
           s.x-opRepVar(p-e.yxy,ecart,dia).x,
           s.x-opRepVar(p-e.yyx,ecart,dia).x));
    float b=dot(n,normalize(prp-p));
    gl_FragColor=vec4((b*c+pow(b,8.0))*(1.0-f*.01),1.0);//simple phong LightPosition=CameraPosition
  }
  else gl_FragColor=vec4(0,0,0,1); //background color
}
`;
var vert=`
#ifdef GL_ES
      precision highp float;
      precision highp int;
    #endif
		#extension GL_OES_standard_derivatives : enable
    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;
    attribute vec4 aVertexColor;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec4 var_vertCol;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);

      // just passing things through
      var_vertPos      = aPosition;
      var_vertCol      = aVertexColor;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
    }
`;

